// PSU value index — record JAH-GPC-PSU-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"wattage": 750, "eff_pct": 90, "price_usd": 110};
var value = (m.wattage*m.eff_pct/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-PSU-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-PSU-000001|' + value.toFixed(2) + ' value index');

